<?php
$categories = $db->query("SELECT id_kategori,nama_kategori FROM tbl_kategori WHERE status_kategori='aktif' ORDER BY nama_kategori")->fetchAll();
$q = trim((string)($_GET['q'] ?? '')); $cat = (int)($_GET['cat'] ?? 0); $status = (string)($_GET['status'] ?? 'aktif');
$where = []; $args = [];
if ($q !== '') { $where[] = '(p.nama_produk LIKE ? OR p.sku LIKE ? OR p.barcode LIKE ?)'; array_push($args,"%$q%","%$q%","%$q%"); }
if ($cat > 0) { $where[] = 'p.id_kategori=?'; $args[]=$cat; }
if (in_array($status,['aktif','nonaktif'],true)) { $where[] = 'p.status_produk=?'; $args[]=$status; }
$filterSql = $where ? 'WHERE '.implode(' AND ',$where) : '';
$count = $db->prepare("SELECT COUNT(*) FROM tbl_produk p {$filterSql}"); $count->execute($args); $total=(int)$count->fetchColumn();
$pageNo=max(1,(int)($_GET['p']??1)); $perPage=10; $offset=($pageNo-1)*$perPage;
$stmt=$db->prepare("SELECT p.*,k.nama_kategori FROM tbl_produk p JOIN tbl_kategori k ON k.id_kategori=p.id_kategori {$filterSql} ORDER BY p.id_produk DESC LIMIT {$perPage} OFFSET {$offset}"); $stmt->execute($args); $products=$stmt->fetchAll();
$categoryCounts=$db->query("SELECT k.id_kategori,k.nama_kategori,COUNT(p.id_produk) jumlah FROM tbl_kategori k LEFT JOIN tbl_produk p ON p.id_kategori=k.id_kategori AND p.status_produk='aktif' WHERE k.status_kategori='aktif' GROUP BY k.id_kategori ORDER BY k.nama_kategori")->fetchAll();
$params=['q'=>$q,'cat'=>$cat,'status'=>$status];
?>
<div class="page-heading"><div><span class="section-kicker">KATALOG TOKO</span><h1>Manajemen Produk</h1><p>Atur barang, harga, dan persediaan WarungMadura.</p></div><?php if(Auth::isAdmin()): ?><div class="heading-actions"><button type="button" class="btn btn-outline-primary" aria-label="Buka form Import CSV" data-bs-toggle="modal" data-bs-target="#importModal"><i class="bi bi-file-earmark-spreadsheet me-2"></i>Import CSV</button><button type="button" class="btn btn-primary" aria-label="Buka form Tambah Produk" data-bs-toggle="modal" data-bs-target="#productModal"><i class="bi bi-plus-lg me-2"></i>Tambah Produk</button></div><?php endif; ?></div>
<div class="category-strip">
    <a class="category-chip <?= $cat===0?'active':'' ?>" href="<?= e(url('products',['q'=>$q,'status'=>$status])) ?>"><span class="category-chip-icon"><i class="bi bi-grid"></i></span><span>Semua Produk</span><small><?= array_sum(array_map('intval',array_column($categoryCounts,'jumlah'))) ?></small></a>
    <?php foreach ($categoryCounts as $c): ?><a class="category-chip <?= $cat===(int)$c['id_kategori']?'active':'' ?>" href="<?= e(url('products',['cat'=>$c['id_kategori'],'q'=>$q,'status'=>$status])) ?>"><span class="category-chip-icon"><i class="bi bi-box2"></i></span><span><?= e($c['nama_kategori']) ?></span><small><?= (int)$c['jumlah'] ?></small></a><?php endforeach; ?>
</div>
<div class="panel-card">
    <div class="filter-toolbar"><form method="get" class="filter-form"><input type="hidden" name="page" value="products"><div class="search-box"><i class="bi bi-search"></i><input type="search" name="q" value="<?= e($q) ?>" placeholder="Cari nama produk, SKU, barcode..."></div><select class="form-select" name="cat"><option value="0">Semua kategori</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id_kategori'] ?>" <?= $cat===(int)$c['id_kategori']?'selected':'' ?>><?= e($c['nama_kategori']) ?></option><?php endforeach; ?></select><select class="form-select" name="status"><option value="aktif" <?= $status==='aktif'?'selected':'' ?>>Produk aktif</option><option value="nonaktif" <?= $status==='nonaktif'?'selected':'' ?>>Produk nonaktif</option><option value="semua" <?= $status==='semua'?'selected':'' ?>>Semua status</option></select><button class="btn btn-dark-soft">Filter</button></form><span class="result-count">Menampilkan <?= count($products) ?> dari <?= $total ?> produk</span></div>
    <div class="table-responsive"><table class="table app-table align-middle"><thead><tr><th>Produk</th><th>SKU / Barcode</th><th>Kategori</th><th>Harga Jual</th><th>Stok</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody>
    <?php if (!$products): ?><tr><td colspan="7"><div class="empty-state"><i class="bi bi-inbox"></i><b>Produk belum ditemukan</b><span>Coba ubah kata kunci atau filter kategori.</span></div></td></tr><?php endif; ?>
    <?php foreach($products as $p): ?><tr>
        <?php $imageSrc = product_image_src($p['gambar']); ?>
        <td><div class="product-cell"><div class="product-thumb"><?php if ($imageSrc): ?><img src="<?= e($imageSrc) ?>" alt="Gambar <?= e($p['nama_produk']) ?>" loading="lazy"><?php else: ?><i class="bi bi-box-seam"></i><?php endif; ?></div><div><b><?= e($p['nama_produk']) ?></b><small><?= e($p['satuan']) ?></small></div></div></td>
        <td>
            <b class="small"><?= e($p['sku']) ?></b>
            <small class="d-block text-muted"><?= e($p['barcode'] ?: $p['sku']) ?></small>
            <?php $barcodeCode = $p['barcode'] ?: $p['sku']; ?>
            <svg class="product-barcode" data-barcode="<?= e($barcodeCode) ?>" role="img" aria-label="Barcode <?= e($barcodeCode) ?>"></svg>
        </td>
        <td><b class="table-main"><?= e($p['nama_kategori']) ?></b></td>
        <td class="fw-semibold"><?= money($p['harga_jual']) ?></td><td><span class="stock-pill <?= (int)$p['stok'] <= (int)$p['stok_minimum']?'low':'' ?>"><?= (int)$p['stok'] ?> <?= e($p['satuan']) ?></span><small class="d-block text-muted">Min. <?= (int)$p['stok_minimum'] ?></small></td><td><?= status_badge($p['status_produk']) ?></td>
        <td class="text-end"><div class="table-actions">
            <?php if(Auth::isAdmin()): ?><button type="button" class="btn btn-sm btn-light product-action" aria-label="Edit <?= e($p['nama_produk']) ?>" data-bs-toggle="modal" data-bs-target="#editProduct<?= (int)$p['id_produk'] ?>"><i class="bi bi-pencil"></i><span>Edit</span></button><?php endif; ?>
            <a class="btn btn-sm btn-light" title="Tambah stok" aria-label="Tambah stok <?= e($p['nama_produk']) ?>" href="<?= e(url('stock',['product'=>$p['id_produk']])) ?>"><i class="bi bi-box-arrow-in-down"></i></a>
            <?php if(Auth::isAdmin() && $p['status_produk']==='aktif'): ?><form method="post" onsubmit="return confirm('Nonaktifkan produk ini? Data transaksi lama tetap disimpan.');"><?= Csrf::field() ?><input type="hidden" name="action" value="deactivate_product"><input type="hidden" name="_return" value="products"><input type="hidden" name="id_produk" value="<?= (int)$p['id_produk'] ?>"><button type="submit" class="btn btn-sm btn-light text-danger" title="Nonaktifkan" aria-label="Nonaktifkan <?= e($p['nama_produk']) ?>"><i class="bi bi-slash-circle"></i></button></form><?php endif; ?>
        </div></td>
    </tr>
    <?php endforeach; ?>
    </tbody></table></div>
    <div class="panel-footer"><span class="text-muted small">Halaman <?= $pageNo ?> · <?= $perPage ?> data per halaman</span><?php pagination($total,$pageNo,$perPage,'products',$params); ?></div>
</div>

